// eslint-disable-next-line import/no-extraneous-dependencies
import { rest } from 'msw';
import queryString from 'query-string';
import { SPLUNK_AUTH_TEST_URL, ERROR_REQUEST_URL } from '@utils/constants';
import formDataResponse from '../fixtures/formDataResponse.json';
import testErrorResponse from '../fixtures/testErrorResponse.json';
import errorFieldResponse from '../fixtures/errorFieldResponse.json';

export const handlers = [
    rest.get(SPLUNK_AUTH_TEST_URL, (_req, res, ctx) => {
        const shouldReturnError = _req.url.searchParams.get('shouldReturnError');
        if (shouldReturnError) {
            return res(ctx.status(400), ctx.json(testErrorResponse));
        }
        return res(ctx.json(formDataResponse));
    }),
    rest.get(ERROR_REQUEST_URL, (_req, res, ctx) => {
        return res(ctx.status(400), ctx.text('error'));
    }),
    rest.post(SPLUNK_AUTH_TEST_URL, async (_req, res, ctx) => {
        const body = await _req.text();
        const parsedBody = queryString.parse(body);

        if (parsedBody.errorField) {
            return res(ctx.status(400), ctx.json(errorFieldResponse));
        }

        return res(ctx.json(formDataResponse));
    }),
];
