type primitives = string | number | boolean;

type nonNestedObject = Record<string, primitives>;

export enum TrackingEvents {
    load = 'passwordManagementPage.load',
    submitBtnClicked = 'passwordManagementPage.submitBtnClicked',
    errorOnSubmit = 'passwordManagementPage.errorOnSubmit',
}

export interface ITrackEventFnParam {
    type: TrackingEvents;
    data?: Record<string, primitives | nonNestedObject>;
}

export interface ITrackEventFn {
    (param: ITrackEventFnParam): void;
}
