import { $any } from '@splunk/sui-form-renderer';
import { findErrorMessage } from '@splunk/splunk-utils/fetch';
import { IErrorMessage, IFormData, IFormDataResponse, IPropertiesSchema } from '@interfaces/app.interfaces';
import { MESSAGES } from '@utils/messages';
import { JsonFormsCore } from '@jsonforms/core';

export const getFormData = (response: IFormDataResponse): IFormData => {
    return response.entry.find((item) => item.name === 'splunk_auth')?.content;
};

export const booleanToString = (data: $any): string | $any => {
    if (typeof data === 'boolean') {
        return data.toString();
    }
    return data;
};

export const booleanStringToNumericString = (data: string): string => {
    if (data === 'true') {
        return '1';
    }
    if (data === 'false') {
        return '0';
    }
    return data;
};

export const formatFormData = (data: IFormData, options?: { useNumericConversion: boolean }): IFormData => {
    const booleanToStringKeys = new Set([
        'enablePasswordHistory',
        'expireUserAccounts',
        'lockoutUsers',
        'verboseLoginFailMsg',
    ]);
    const excludeKeys = new Set(['eai:acl']);

    const formatter = options?.useNumericConversion ? booleanStringToNumericString : booleanToString;

    return Object.entries(data).reduce((acc, [key, value]) => {
        if (!excludeKeys.has(key)) {
            acc[key] = booleanToStringKeys.has(key) ? formatter(value) : value;
        }
        return acc;
    }, {} as IFormData);
};

export const isJsonContentType = (response: Response): boolean => {
    const contentType = response.headers.get('Content-Type');
    return contentType && contentType.toLowerCase().includes('application/json');
};

export const formatSplunkDError = (splunkdJson: $any): string => {
    const errorMessage = findErrorMessage(splunkdJson);
    return errorMessage?.text || MESSAGES.ERRORS.DEFAULT;
};

export const getFormErrors = (formErrors: JsonFormsCore['errors']): string[] => {
    return formErrors
        .map(({ parentSchema, dataPath }) => {
            const { errorMessage } = parentSchema as IErrorMessage;
            if (errorMessage) {
                return errorMessage;
            }

            const { properties } = parentSchema as IPropertiesSchema;
            return properties?.[dataPath]?.errorMessage;
        })
        .filter((item) => item !== undefined);
};
