export type TestIDObject = {
    [key: string]: string;
};

type NormalizeTestIdsParams = {
    appName: string;
    componentName: string;
    testIds: TestIDObject;
};

export const normalizeDataTestIds = ({
    appName = '',
    componentName = '',
    testIds,
}: NormalizeTestIdsParams): TestIDObject => {
    Object.keys(testIds).forEach((key) => {
        // eslint-disable-next-line no-param-reassign
        testIds[key] = [appName, componentName, testIds[key]].concat().join('-');
    });
    return testIds;
};
