import queryString from 'query-string';
import { defaultFetchInit } from '@splunk/splunk-utils/fetch';
import { createRESTURL } from '@splunk/splunk-utils/url';
import { IFormData, IFormDataResponse } from '@interfaces/app.interfaces';
import { formatSplunkDError, getFormData, isJsonContentType } from '@utils/helpers';
import { SPLUNK_AUTH_URL } from '@utils/constants';
import { MESSAGES } from '@utils/messages';

export const fetchData = async (): Promise<IFormData> => {
    const url = createRESTURL(`${SPLUNK_AUTH_URL}?output_mode=json`);
    const response = await fetch(url);

    if (isJsonContentType(response)) {
        const json = await response.json();
        if (response.ok) {
            return getFormData(json);
        }
        throw new Error(formatSplunkDError(json));
    }

    throw new Error(MESSAGES.ERRORS.DEFAULT);
};

export const updatePasswordConfig = async (formData: IFormData): Promise<IFormData> => {
    const url = createRESTURL(SPLUNK_AUTH_URL);
    const body = queryString.stringify(formData);
    const fetchOptions = { ...defaultFetchInit, method: 'POST', body };
    const response = await fetch(url, fetchOptions);
    const json: IFormDataResponse = await response.json();

    if (!response.ok) {
        throw new Error(formatSplunkDError(json));
    }
    return getFormData(json);
};
