import {
    IFormData,
    IGenerateUISchemaFn,
    UIElementTypes,
    UISchemaElementOptions,
} from '@interfaces/app.interfaces';
import { MESSAGES } from '@utils/messages';
import { RuleEffect } from '@jsonforms/core';

const { FORM } = MESSAGES;
const { Label, Control, RadioBarGroup } = UIElementTypes;

const getInputOptions = (name: keyof IFormData): UISchemaElementOptions => ({
    suiControlGroupProps: {
        labelWidth: 160,
    },
    suiComponentProps: {
        name,
        'data-name': name,
    },
});

const getRadioOptions = (name: keyof IFormData): UISchemaElementOptions => ({
    suiControlGroupProps: {
        labelOptions: {
            allowEmptyLabel: true,
        },
        labelWidth: 160,
    },
    radioBarOptionProps: {
        name,
    },
    radioBarProps: {
        'data-name': name,
    },
});

