import React, { ReactElement, useEffect, useState } from 'react';
import { SplunkThemeProvider, pick, variables } from '@splunk/themes';
import { getUserTheme } from '@splunk/splunk-utils/themes';
import WaitSpinner from '@splunk/react-ui/WaitSpinner';
import styled from 'styled-components';
import { IconsTypes, UserThemesTypes } from '@interfaces/app.interfaces';
import { MESSAGES } from '@utils/messages';
import { TEST_IDS } from '@utils/testIds';
import { Header } from './components/header/Header';
import { PasswordManagementForm } from './components/password-management-form/PasswordManagementForm';

const WrapperDiv = styled.div`
    max-width: 960px;
    padding: 30px 20px 20px 20px;
    background-color: ${pick({
        enterprise: variables.backgroundColor,
        prisma: variables.backgroundColorPopup,
    })};
    box-shadow: ${variables.overlayShadow};
    margin: 0 auto 20px;
    display: flex;
    flex-direction: column;
`;

export const App = (): ReactElement => {
    const [theme, setTheme] = useState<UserThemesTypes>();
    if (process.env.goal === 'local') {
        // eslint-disable-next-line global-require
        const { worker } = require('./mocks/browser');
        worker.start();
    }

    useEffect(() => {
        async function getTheme(): Promise<void> {
            try {
                const userTheme = await getUserTheme();
                setTheme(userTheme);
            } catch (error) {
                setTheme(UserThemesTypes.light);
            }
        }

        if (process.env.goal !== 'local') {
            getTheme();
        } else {
            setTheme(UserThemesTypes.light);
        }
    }, []);

    if (!theme) {
        return <WaitSpinner size="medium" data-test={TEST_IDS.SPINNER} />;
    }

    const { HEADER } = MESSAGES;
    return (
        <SplunkThemeProvider family="enterprise" colorScheme={theme}>
            <WrapperDiv className="management-passwordconfig" data-view="views/management/PasswordConfig">
                <Header title={HEADER.TITLE} description={HEADER.DESCRIPTION} iconType={IconsTypes.info} />
                <PasswordManagementForm />
            </WrapperDiv>
        </SplunkThemeProvider>
    );
};
