import { FC } from 'react';
import { createRemote } from '@splunk/skinny-bundle-loader';
import { App } from './App';

export const ConfigPageRendererRemote: FC = App;

/**
 *  ConfigPageRendererRemote is the remote component that gets exposed to the shell
 */
const RootRemote = {
    root: ConfigPageRendererRemote,
};

// eslint-disable-next-line
declare let __webpack_public_path__: any;

export default createRemote(RootRemote, (fnConfig) => {
    // eslint-disable-next-line
    __webpack_public_path__ = (() => {
        return `${fnConfig.remoteRoot}/`;
    })();
});
