import { ElementTypes, IGenerateSchemaFn } from '@interfaces/app.interfaces';
import { MESSAGES } from '@utils/messages';

const { boolean, integer, object, string, number } = ElementTypes;
const { FORM } = MESSAGES;

export const generateSchema: IGenerateSchemaFn = () => ({
    type: object,
    properties: {
        minPasswordLength: {
            description: FORM.MIN_PASSWORD_LENGTH.DESCRIPTION,
            type: integer,
            minimum: 1,
            maximum: 256,
            errorMessage: FORM.MIN_PASSWORD_LENGTH.ERR,
        },
        minPasswordDigit: {
            description: FORM.MIN_PASSWORD_DIGIT.DESCRIPTION,
            type: integer,
            minimum: 0,
            maximum: 256,
            errorMessage: FORM.MIN_PASSWORD_DIGIT.ERR,
        },
        minPasswordLowercase: {
            description: FORM.MIN_PASSWORD_LOWERCASE.DESCRIPTION,
            type: integer,
            minimum: 0,
            maximum: 256,
            errorMessage: FORM.MIN_PASSWORD_LOWERCASE.ERR,
        },
        minPasswordUppercase: {
            description: FORM.MIN_PASSWORD_UPPERCASE.DESCRIPTION,
            type: integer,
            minimum: 0,
            maximum: 256,
            errorMessage: FORM.MIN_PASSWORD_UPPERCASE.ERR,
        },
        minPasswordSpecial: {
            description: FORM.MIN_PASSWORD_SPECIAL.DESCRIPTION,
            type: integer,
            minimum: 0,
            maximum: 256,
            errorMessage: FORM.MIN_PASSWORD_SPECIAL.ERR,
        },
        expireUserAccounts: {
            type: string,
            enum: ['true', 'false'],
        },
        expirePasswordDays: {
            description: FORM.EXPIRE_PASSWORD_DAYS.DESCRIPTION,
            type: integer,
            minimum: 0,
            maximum: 3650,
            errorMessage: FORM.EXPIRE_PASSWORD_DAYS.ERR,
        },
        expireAlertDays: {
            description: FORM.EXPIRE_ALERT_DAYS.DESCRIPTION,
            type: integer,
            minimum: 0,
            maximum: 120,
            errorMessage: FORM.EXPIRE_ALERT_DAYS.ERR,
        },
        enablePasswordHistory: {
            type: string,
            enum: ['true', 'false'],
        },
        passwordHistoryCount: {
            description: FORM.PASSWORD_HISTORY_COUNT.DESCRIPTION,
            type: integer,
            minimum: 1,
            maximum: 128,
            errorMessage: FORM.PASSWORD_HISTORY_COUNT.ERR,
        },
        constantLoginTime: {
            description: FORM.CONSTANT_LOGIN_TIME.DESCRIPTION,
            type: number,
            minimum: 0,
            maximum: 5,
            errorMessage: FORM.CONSTANT_LOGIN_TIME.ERR,
        },
        verboseLoginFailMsg: {
            type: string,
            enum: ['true', 'false'],
            description: FORM.VERBOSE_LOGIN_FAIL_MSG.DESCRIPTION,
        },
        forceWeakPasswordChange: {
            type: boolean,
        },
        lockoutUsers: {
            type: string,
            enum: ['true', 'false'],
        },
        lockoutAttempts: {
            description: FORM.LOCKOUT_ATTEMPTS.DESCRIPTION,
            type: integer,
            minimum: 1,
            maximum: 64,
            errorMessage: FORM.LOCKOUT_ATTEMPTS.ERR,
        },
        lockoutThresholdMins: {
            description: FORM.LOCKOUT_THRESHOLD_MINS.DESCRIPTION,
            type: integer,
            minimum: 1,
            maximum: 120,
            errorMessage: FORM.LOCKOUT_THRESHOLD_MINS.ERR,
        },
        lockoutMins: {
            description: FORM.LOCKOUT_MINS.DESCRIPTION,
            type: integer,
            minimum: 1,
            maximum: 1440,
            errorMessage: FORM.LOCKOUT_MINS.ERR,
        },
    },
    required: [
        'minPasswordLength',
        'minPasswordDigit',
        'minPasswordLowercase',
        'minPasswordUppercase',
        'minPasswordSpecial',
        'expirePasswordDays',
        'expireAlertDays',
        'passwordHistoryCount',
        'constantLoginTime',
        'lockoutAttempts',
        'lockoutThresholdMins',
        'lockoutMins',
    ],
});
