import React, { FC } from 'react';
import styled from 'styled-components';
import Heading from '@splunk/react-ui/Heading';
import P from '@splunk/react-ui/Paragraph';
import { IconsTypes } from '@interfaces/app.interfaces';
import { TEST_IDS } from '@utils/testIds';
import { variables } from '@splunk/themes';
import { Icon } from '../icon/Icon';

const SectionTitle = styled(Heading)`
    margin-top: 0;
    font-size: ${variables.fontSizeXXLarge};
    font-weight: ${variables.fontWeightSemiBold};
    line-height: ${variables.fontSizeXXLarge};
`;

const HeaderDescription = styled(P)`
    margin: 0 0 ${variables.spacingQuarter} 0;
`;

interface HeaderProps {
    title: string;
    description?: string;
    iconType?: IconsTypes;
}

export const Header: FC<HeaderProps> = ({ title, iconType, description }) => {
    return (
        <div className="section-padded section-header" data-test={TEST_IDS.HEADER_CONTAINER}>
            <SectionTitle level={1} data-test={TEST_IDS.HEADER_TITLE}>
                {title}
            </SectionTitle>
            {description && (
                <HeaderDescription data-test={TEST_IDS.HEADER_DESCRIPTION}>
                    {iconType && <Icon iconType={iconType} />}
                    <span>{description}</span>
                </HeaderDescription>
            )}
        </div>
    );
};
