import React, { ReactElement, useEffect, useState } from 'react';
import { $any, Errors, ISubmitHandler, SUIFormRendererCompound } from '@splunk/sui-form-renderer';
import { TEST_IDS } from '@utils/testIds';
import { IFormData, IFromOnChangeData } from '@interfaces/app.interfaces';
import { formatFormData, getFormErrors } from '@utils/helpers';
import { fetchData, updatePasswordConfig } from '@services/appServices';
import { MESSAGES } from '@utils/messages';
import { trackingService } from '@services/trackingService';
import Code from '@splunk/react-ui/Code';
import { TrackingEvents } from '@interfaces/trackingService.interfaces';
import {
    ActionAreaWrapper,
    ErrorsWrapper,
    MainSectionWrapper,
    WrapperDiv,
} from './passwordManagementForm.styles';
import { generateSchema } from './schema';
import { generateUISchema } from './uiSchema';

export const PasswordManagementForm = (): ReactElement => {
    const [formData, setFormData] = useState<IFormData>();
    const [errorMessages, setErrorMessages] = useState<string[]>([]);
    const [isTrackingLogVisible, setIsTrackingLogVisible] = useState(false);

    useEffect(() => {
        async function getFormData(): Promise<void> {
            try {
                const formDataObj = await fetchData();
                setFormData(formatFormData(formDataObj));
            } catch (error) {
                setErrorMessages([error.message || MESSAGES.ERRORS.DEFAULT]);
            }
        }

        getFormData();
    }, []);

    useEffect(() => {
        trackingService.trackEvent({
            type: TrackingEvents.load,
            data: {
                pageLoaded: MESSAGES.HEADER.TITLE,
            },
        });
        const dblClickHandler = (event): void => {
            if (event.shiftKey && event.altKey) {
                setIsTrackingLogVisible((prevValue) => !prevValue);
            }
        };
        window.addEventListener('dblclick', dblClickHandler);

        return (): void => window.removeEventListener('dblclick', dblClickHandler);
    }, []);

    const dismissErrorMessage = (): void => setErrorMessages([]);

    const handleSubmit: ISubmitHandler<$any> = async ({ data, successCb, failureCb }) => {
        try {
            const preparedData = formatFormData(data, { useNumericConversion: true });
            const formDataObj = await updatePasswordConfig({ ...preparedData, output_mode: 'json' });
            setFormData(formatFormData(formDataObj));
            successCb();

            trackingService.trackEvent({
                type: TrackingEvents.submitBtnClicked,
                data,
            });
        } catch (error) {
            failureCb([error.message]);

            trackingService.trackEvent({
                type: TrackingEvents.errorOnSubmit,
                data: {
                    errorUseCases: error.message,
                },
            });
        }
    };

    const onChangeHandler = (data: IFromOnChangeData): void => {
        const formErrors = getFormErrors(data.errors);
        if (formErrors.length !== errorMessages.length) {
            setErrorMessages(formErrors);
        }
    };

    const saveButtonProps = {
        className: 'btn-primary',
    };

    return (
        <WrapperDiv data-test={TEST_IDS.FORM_CONTAINER}>
            {errorMessages.length > 0 && (
                <ErrorsWrapper>
                    <Errors errorMessages={errorMessages} onRequestRemove={dismissErrorMessage} />
                </ErrorsWrapper>
            )}
            <SUIFormRendererCompound>
                <MainSectionWrapper>
                    <SUIFormRendererCompound.ErrorView />
                    <SUIFormRendererCompound.Form
                        schema={generateSchema()}
                        uischema={generateUISchema()}
                        data={formData}
                        onChange={onChangeHandler}
                    />
                </MainSectionWrapper>
                <footer>
                    <ActionAreaWrapper data-test={TEST_IDS.FORM_ACTIONS}>
                        <SUIFormRendererCompound.ActionButtons
                            hideCancel
                            onSubmit={handleSubmit}
                            saveButtonProps={saveButtonProps}
                        />
                    </ActionAreaWrapper>
                </footer>
            </SUIFormRendererCompound>
            {isTrackingLogVisible && (
                <Code value={JSON.stringify(trackingService.getTrackingLogs(), null, 4)} language="json" />
            )}
        </WrapperDiv>
    );
};
