import { JsonSchema4, JsonSchema7, JsonFormsCore } from '@jsonforms/core';
import { $any } from '@splunk/sui-form-renderer';

export enum IconsTypes {
    info = 'info',
}

export enum ElementTypes {
    boolean = 'boolean',
    integer = 'integer',
    number = 'number',
    object = 'object',
    string = 'string',
}

export enum UserThemesTypes {
    light = 'light',
    dark = 'dark',
}

export interface IGenerateSchemaFn {
    (): JsonSchema4 | JsonSchema7;
}

export enum UIElementTypes {
    Control = 'Control',
    Label = 'Label',
    RadioBarGroup = 'RadioBarGroup',
}

export type UISchemaElementOptions = Record<string, $any>;

interface IUISchemaElement {
    label?: string;
    options?: UISchemaElementOptions;
    rule?: $any;
    scope?: string;
    text?: string;
    type: UIElementTypes;
}

export interface IGenerateUISchemaFn {
    (): {
        type: 'VerticalLayout';
        elements: IUISchemaElement[];
    };
}

export type RadioBarValue = string | boolean;

export interface IFormData {
    output_mode?: string;
    constantLoginTime: number;
    enablePasswordHistory: RadioBarValue;
    expireAlertDays: number;
    expirePasswordDays: number;
    expireUserAccounts: RadioBarValue;
    forceWeakPasswordChange: boolean;
    lockoutAttempts: number;
    lockoutMins: number;
    lockoutThresholdMins: number;
    lockoutUsers: RadioBarValue;
    minPasswordDigit: number;
    minPasswordLength: number;
    minPasswordLowercase: number;
    minPasswordSpecial: number;
    minPasswordUppercase: number;
    passwordHistoryCount: number;
    verboseLoginFailMsg: RadioBarValue;
}

interface IFormDataResponseEntry {
    name: string;
    id: string;
    updated: string;
    links: {
        alternate: string;
        list: string;
        edit: string;
    };
    author: string;
    acl: {
        app: string;
        can_list: boolean;
        can_write: boolean;
        modifiable: boolean;
        owner: string;
        perms: {
            read: string[];
            write: string[];
        };
        removable: boolean;
        sharing: string;
    };
    fields: {
        required: string[];
        optional: string[];
        wildcard: string[];
    };
    content: IFormData;
}

export interface IFormDataResponse {
    links: {
        [key: string]: string;
    };
    origin: string;
    updated: string;
    generator: {
        build: string;
        version: string;
    };
    entry: IFormDataResponseEntry[];
    paging: {
        total: number;
        perPage: number;
        offset: number;
    };
    messages: string[];
}

export interface IFromOnChangeData {
    data: IFormData;
    errors: JsonFormsCore['errors'];
}

export interface IErrorMessage {
    errorMessage: string;
}
export interface IPropertiesSchema {
    properties: {
        [key: string]: {
            errorMessage: string;
        };
    };
}
